import os

def category(filename):
    ext = os.path.splitext(filename)[1].lower()
    groups = {
        'Images': {'.jpg', '.jpeg', '.png', '.gif'},
        'Documents': {'.pdf', '.txt', '.docx'},
        'Code': {'.py', '.js', '.html'},
    }
    for name, extensions in groups.items():
        if ext in extensions:
            return name
    return 'Other'
